const EXPECTED_TOKEN = 'REPLACE_WITH_ADVANCE_INTERNAL_TOKEN';
const item = $input.first();
const headers = item.json.headers || {};
const token = headers['x-advance-token'];
if (token !== EXPECTED_TOKEN) {
  // review 2026-09-14 (H3): an empty item here made n8n answer 200 with no
  // `sent` key, which the app read as SENT. A bad token must be a hard 500.
  throw new Error('internal-send-outlook: bad X-Advance-Token');
}
return [{ json: item.json }];

// 2026-09-13 audit #3: a send only counts when Graph accepted it (202).
// A known non-202 status throws, which makes this webhook answer 500, so the
// Flask app records it as NOT sent (retries next run, alerts Brian) instead
// of believing a 200 from a request Graph actually rejected.
// If the status can't be read at all, this does NOT throw: a real 202 must
// never be reported as a failure (that would re-send to a band next run).
const r = $input.first().json;
const status = (typeof r.statusCode === 'number') ? r.statusCode : null;
const b = $('Trigger').first().json.body || {};
const empty = !String(b.html || b.body || '').trim();
if (status !== null && status !== 202) {
  throw new Error('Graph did not accept the message: HTTP ' + status + ' ' + JSON.stringify(r.body || '').slice(0, 300));
}
if (empty) {
  return [{ json: { sent: false, status, blocked: 'empty body' } }];
}
return [{ json: { sent: true, status } }];
